def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_last = opp[-1]
    my_last = me[-1]

    total_c = opp.count('C')
    total_d = n - total_c

    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    # Immediate revenge on first observed defection, but then use adaptive logic
    if n == 2:
        if opp_last == 'C':
            return 'C'
        if opp[0] == 'D':
            return 'D'
        return 'D'

    # Identify unconditional strategies
    if total_d == n:
        return 'D'
    if total_c == n:
        if n >= 95:
            return 'D'
        return 'C'

    # Recent window analysis
    window = min(12, n)
    recent_opp = opp[-window:]
    recent_me = me[-window:]
    roc = recent_opp.count('C')
    rod = window - roc

    # Consecutive opponent defections at the end
    streak_d = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        streak_d += 1
        i -= 1

    # Consecutive opponent cooperations at the end
    streak_c = 0
    i = n - 1
    while i >= 0 and opp[i] == 'C':
        streak_c += 1
        i -= 1

    # Endgame exploitation
    remaining = 100 - n
    if remaining <= 4:
        if total_c > total_d:
            return 'D'
        return 'D'

    # Strongly defective opponent -> defect
    if rod >= 8 and rod > roc:
        return 'D'

    # If opponent just defected
    if opp_last == 'D':
        if streak_d >= 2:
            # punish sustained defection unless very cooperative historically
            if total_c > total_d + 10:
                if rng.random() < 0.35:
                    return 'C'
            return 'D'
        # single defection: retaliate but forgive if opponent mostly cooperative
        if total_c >= total_d + 3 and roc >= 2:
            if streak_c == 0 and rng.random() < 0.5:
                return 'C'
        return 'D'

    # Opponent cooperated last
    # If we defected last, restore cooperation unless opponent is exploitable
    if my_last == 'D':
        if total_c >= total_d:
            return 'C'
        # if opponent has been forgiving despite our defections, keep exploiting
        if streak_c >= 2 and recent_me.count('D') <= 2:
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # Opponent cooperative: mostly cooperate, with rare probing if very safe
    if total_c >= total_d:
        # Occasional test defection against extremely cooperative opponents
        if total_d == 0 and n >= 15 and n % 19 == 0:
            return 'D'
        if roc >= window - 1:
            return 'C'
        # If we've been fully cooperative and opponent has defected only once
        if total_d == 1 and my_last == 'C' and streak_c >= 3:
            return 'C'
        return 'C'
    else:
        # Opponent more defective than cooperative: be defensive
        if rng.random() < 0.3:
            return 'C'
        return 'D'
